import {discover,agents} from './data.js';import {dataProvider,walletAdapter,verifiedTradeUrl} from './adapters.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let tokens=[],snapshot=null,returnFocus;const dialog=$('#dossier');
function show(html){returnFocus=document.activeElement;$('#dialog-content').innerHTML=html;dialog.showModal();$('#close-dialog').focus()}function close(){dialog.close()}$('#close-dialog').onclick=close;dialog.addEventListener('close',()=>returnFocus?.focus());
function dossier(t){const url=verifiedTradeUrl(t);show(`<span class="mono red">FINALIZED CREATION / MAINNET</span><h2 id="dialog-title">${esc(t.name)} / $${esc(t.ticker)}</h2><p>${esc(t.narrative||'Token name and symbol decoded from the on-chain creation instruction.')}</p><dl><dt>MINT</dt><dd>${esc(t.mint)}</dd><dt>LAUNCH PAYER</dt><dd>${esc(t.payer)}</dd><dt>CREATOR WALLET</dt><dd>${esc(t.creatorWallet)}</dd><dt>BLOCK TIME / SLOT</dt><dd>${esc(t.timestamp||'Unavailable')} / ${esc(t.slot)}</dd><dt>VERIFICATION</dt><dd>Successful finalized transaction invoking Pump ${esc(t.instruction)}. Checked ${esc(t.verifiedAt)}.</dd><dt>ATTRIBUTION</dt><dd>${esc(t.attribution||'External token. No DIT agent attribution. The chain does not prove AI authorship.')}</dd><dt>MARKET DATA</dt><dd>Not connected. No market-cap or trading figures are estimated.</dd></dl><div class="hero-actions">${url?`<a class="button primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">VIEW ON PUMP.FUN ↗</a>`:''}<a class="button secondary" href="${esc(t.explorerUrl)}" target="_blank" rel="noopener noreferrer">VERIFY TRANSACTION ↗</a><a class=\"button secondary\" href=\"#evidence/${esc(t.mint)}\">EVIDENCE FILE</a></div>`)}
function render(){const visible=discover(tokens,{query:$('#search').value,status:$('#status').value,creator:$('#creator').value,sort:$('#sort').value});$('#count').textContent=`${visible.length} / ${tokens.length} VERIFIED AGENT ARTIFACTS`;$('#tokens').innerHTML=visible.length?visible.map(t=>`<article class="token"><div class="token-art"><div class="metal-portrait portrait-${agents.findIndex(a=>a.id===t.creator)}"></div><span class="badge">FINALIZED</span></div><div class="token-body"><div class="token-meta"><span>${esc(t.creator)}</span><span class="state">${esc(t.status)}</span></div><h3>${esc(t.name)} <small>$${esc(t.ticker)}</small></h3><p class="narrative">${esc(t.narrative)}</p><div class="metrics"><div>MARKET CAP<strong>NOT CONNECTED</strong></div><div>TRADING ACTIVITY<strong>NOT CONNECTED</strong></div></div><div class="token-footer"><span>${esc(t.timestamp?.slice(0,10)||'TIME UNKNOWN')}</span><button data-token="${esc(t.id)}">INSPECT EVIDENCE ↗</button></div></div></article>`).join(''):`<div class="empty"><span class="standby-orbit" aria-hidden="true">◉</span><span class="mono red">${tokens.length?'NO MATCHING SIGNALS':'AWAITING FIRST VERIFIED LAUNCH'}</span><h3>${tokens.length?'Nothing matches this frequency.':'The archive starts with proof.'}</h3><p>${tokens.length?'Adjust the filters to recover the signal.':'No agent launch records are configured. A token appears only after its finalized Pump.fun creation matches a registered agent wallet.'}</p><button id="empty-reset">${tokens.length?'Reset filters ↺':'Refresh chain status ↻'}</button></div>`;$('#empty-reset')?.addEventListener('click',()=>tokens.length?reset():refresh());$('#archive-list').innerHTML=visible.length?visible.map(t=>`<button class="archive-row" data-token="${esc(t.id)}"><strong>$${esc(t.ticker)}</strong><span>${esc(t.creator)}</span><span>${esc(t.timestamp)}</span><span>FINALIZED ↗</span></button>`).join(''):'<div class="empty archive-empty"><span class="mono">NO VERIFIED AGENT ARTIFACTS YET. NO FABRICATED HISTORY.</span></div>'}
function reset(){['search','status','creator'].forEach(id=>$('#'+id).value='');$('#sort').value='newest';render()}$('#reset').onclick=reset;$('#search').oninput=render;['status','creator','sort'].forEach(id=>$('#'+id).onchange=render);
function renderAgents(){const connected=snapshot?.chain.status==='connected';$('#agent-grid').innerHTML=agents.map(a=>`<article class="agent"><div class="agent-stage"><div class="metal-portrait portrait-${a.portrait}"></div><span class="badge">${connected?'CHAIN OBSERVER':'STANDBY'}</span><div class="agent-scan"></div><div class="agent-terminal mono">${connected?'RPC / FINALIZED SLOT '+snapshot.chain.slot:'RPC / WAITING FOR CONNECTION'}<br>SIGNER / NOT CONFIGURED</div></div><div class="agent-head"><div><span class="mono small">ENTITY_00${a.portrait+1} / OBSERVER IDENTITY</span><h3>${esc(a.id)}</h3><span class="mono small">${esc(a.name.toUpperCase())}</span></div></div><p>${esc(a.description)}</p><button data-agent="${a.id}">OPEN ENTITY DOSSIER <span>↗</span></button></article>`).join('')}
let refreshing=false;async function refresh(){if(refreshing)return;refreshing=true;try{snapshot=await dataProvider.refresh();tokens=snapshot.tokens;$('#chain-state').textContent=snapshot.chain.status==='connected'?'MAINNET CONNECTED':'RPC UNAVAILABLE';$('#slot').textContent=snapshot.chain.slot?.toLocaleString()||'—';$('#verified-count').textContent=String(tokens.length).padStart(2,'0');$('#chain-update').textContent=snapshot.chain.checkedAt?'LAST VERIFIED '+new Date(snapshot.chain.checkedAt).toLocaleTimeString():'RPC UNAVAILABLE — RETRYING';if(snapshot.failures.length)$('#chain-update').textContent+=' / '+snapshot.failures.length+' RECORDS FAILED VERIFICATION';render();renderAgents()}catch{$('#chain-state').textContent='UNAVAILABLE';$('#slot').textContent='—';$('#verified-count').textContent='—';$('#chain-update').textContent='SERVER UNAVAILABLE — RETRYING';tokens=[];snapshot=null;render();renderAgents();$('#count').textContent='FEED UNAVAILABLE — NO CACHED DATA PRESENTED AS LIVE'}finally{refreshing=false}}
$('#verify-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('#verify-status').textContent='Checking finalized Solana transaction…';try{const r=await fetch('/api/verify?signature='+encodeURIComponent($('#signature').value.trim()),{signal:AbortSignal.timeout(20000)});const t=await r.json();if(!r.ok)throw Error(t.error||'Verification unavailable');$('#verify-status').textContent='Finalized Pump.fun creation verified. External token; AI authorship not established.';dossier(t)}catch(e){$('#verify-status').textContent=e.message}finally{button.disabled=false}};
document.addEventListener('click',e=>{const el=e.target.closest('[data-token]');if(el)dossier(tokens.find(t=>t.id===el.dataset.token));const ae=e.target.closest('[data-agent]');if(ae){const a=agents.find(a=>a.id===ae.dataset.agent);show(`<span class="mono red">ENTITY DOSSIER / OBSERVER IDENTITY</span><div class="dossier-portrait metal-portrait portrait-${a.portrait}"></div><h2 id="dialog-title">${esc(a.id)}</h2><p>“${esc(a.personality)}”</p><dl><dt>RUNTIME STATUS</dt><dd>Identity designed. Autonomous reasoning and server signer are not configured.</dd><dt>ACTUAL OBSERVATION</dt><dd>${snapshot?.chain.status==='connected'?'Interface observing finalized Solana slot '+snapshot.chain.slot:'Chain RPC is not available.'}</dd><dt>VERIFIED HISTORY</dt><dd>${tokens.filter(t=>t.creator===a.id).length} registered, verified launches.</dd></dl><button class="button primary" id="agent-filter">VIEW ARTIFACTS ↗</button>`);$('#agent-filter').onclick=()=>{reset();$('#creator').value=a.id;render();close();$('#network').scrollIntoView();$('#creator').focus({preventScroll:true})}}});
$('#integration').onclick=()=>{show(`<span class="mono red">NETWORK / INTEGRATION STATUS</span><h2 id="dialog-title">OBSERVE.<br>VERIFY. CONNECT.</h2><dl><dt>SOLANA MAINNET</dt><dd>${snapshot?.chain.status==='connected'?'Connected / finalized commitment':'RPC unavailable'}</dd><dt>AGENT LAUNCHES</dt><dd>Awaiting a funded server signer and approved agent configuration. No tokens have been launched by this application.</dd><dt>TRADING DATA</dt><dd>Provider not configured. No synthetic market statistics.</dd></dl><button class="button primary" id="connect-wallet">CONNECT PHANTOM ↗</button><p id="wallet-message" role="status">Read-only connection. No transaction requested.</p>`);$('#connect-wallet').onclick=async()=>{$('#connect-wallet').disabled=true;const r=await walletAdapter.connect();$('#wallet-message').textContent=r.message;$('#connect-wallet').disabled=false}};
$('#menu').onclick=()=>{const open=$('#menu').getAttribute('aria-expanded')!=='true';$('#menu').setAttribute('aria-expanded',open);$('#nav').classList.toggle('open',open)};$('#nav').onclick=()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')};
render();renderAgents();refresh();setInterval(()=>{if(!document.hidden)refresh()},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
const motion=matchMedia('(prefers-reduced-motion: reduce)');if(!motion.matches){$('.hero').addEventListener('pointermove',e=>{const r=$('.hero').getBoundingClientRect();$('.hero-art').style.setProperty('--pan-x',((e.clientX-r.left)/r.width-.5)*14+'px');$('.hero-art').style.setProperty('--pan-y',((e.clientY-r.top)/r.height-.5)*10+'px')})}
